import { useState } from "react";

function App() {

  const [score, setScore] = useState(0)

  const addScore = () => {
    setScore = (score + 1);
  }

  return (
    <div>
      <h1>{score}</h1>

      <button onClick={addScore}>+</button>
    </div>
  );
}

export default App;
